20	/**
21	 * Resolves an owner's locality (canonical region) from their postcode and city. The postcode is
22	 * preferred: a postcode falling within a known region's range determines the region directly, which
23	 * disambiguates cities that share a name. Only when the postcode is absent or in no known range does
24	 * resolution fall back to the fixed city-to-region table. Inputs matching neither resolve to
25	 * {@link #UNKNOWN}.
26	 */
27	public final class LocalityResolver {
28	
29	    /** Locality returned when neither the postcode nor the city yields a region. */
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private static final Map<String, String> CITY_REGIONS = Map.of(
33	        "Sydney", "NSW",
34	        "Melbourne", "VIC",
35	        "Brisbane", "QLD");
36	
37	    /** Region -> inclusive four-digit postcode range {@code {low, high}}. */
38	    private static final Map<String, int[]> REGION_RANGES = Map.of(
39	        "NSW", new int[] {2000, 2099},
40	        "VIC", new int[] {3000, 3099},
41	        "QLD", new int[] {4000, 4099});
42	
43	    private LocalityResolver() {
44	    }
45	
46	    /**
47	     * Resolve the canonical region, preferring the postcode over the city.
48	     *
49	     * @param postcode the postcode to look up first, or {@code null}/absent
50	     * @param city     the city used as a fallback when the postcode yields no region
51	     * @return the region determined by the postcode's range, or failing that by the
52	     *         city-to-region table, or {@link #UNKNOWN} when neither matches
53	     */
54	    public static String regionFor(String postcode, String city) {
55	        String byPostcode = regionForPostcode(postcode);
56	        return byPostcode != null ? byPostcode : regionForCity(city);
57	    }
58	
59	    /**
60	     * Resolve the canonical region for the given city via the fixed city-to-region table.
61	     *
62	     * @param city the city to look up
63	     * @return the region string, or {@link #UNKNOWN} when the city is not in the table
64	     */
65	    public static String regionForCity(String city) {
66	        return CITY_REGIONS.getOrDefault(city, UNKNOWN);
67	    }
68	
69	    /**
70	     * The inclusive four-digit postcode range for the given region.
71	     *
72	     * @param region the region to look up
73	     * @return a fresh {@code {low, high}} array, or {@code null} when the region has no range
74	     */
75	    public static int[] rangeForRegion(String region) {
76	        int[] range = REGION_RANGES.get(region);
77	        return range == null ? null : range.clone();
78	    }
79	
80	    /**
81	     * The region whose postcode range contains the given postcode.
82	     *
83	     * @param postcode the postcode to classify, or {@code null}/absent
84	     * @return the matching region, or {@code null} when the postcode is absent, not a number, or in
85	     *         no known range
86	     */
87	    private static String regionForPostcode(String postcode) {
88	        if (postcode == null) {
89	            return null;
90	        }
91	        int value;
92	        try {
93	            value = Integer.parseInt(postcode.trim());
94	        }
95	        catch (NumberFormatException ex) {
96	            return null;
97	        }
98	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
99	            int[] range = entry.getValue();
100	            if (value >= range[0] && value <= range[1]) {
101	                return entry.getKey();
102	            }
103	        }
104	        return null;
105	    }
