25	/**
26	 * Builds the stable, shared {@code householdId} for owners living in the same
27	 * household.
28	 *
29	 * <p>The identifier is derived deterministically from the household's identity
30	 * (last name and address, canonicalized by {@link HouseholdNormalizer}), so every
31	 * owner in a household resolves to the same value regardless of registration order.
32	 */
33	@Component
34	public class HouseholdIdGenerator {
35	
36	    private static final int ID_LENGTH = 16;
37	
38	    private final HouseholdNormalizer householdNormalizer;
39	
40	    public HouseholdIdGenerator(HouseholdNormalizer householdNormalizer) {
41	        this.householdNormalizer = householdNormalizer;
42	    }
43	
44	    /**
45	     * Build the household identifier shared by owners with the given last name and
46	     * address.
47	     *
48	     * @param lastName the household's last name
49	     * @param address  the household's address
50	     * @return a stable, upper-case hexadecimal identifier for the household
51	     */
52	    public String generate(String lastName, String address) {
53	        String key = householdNormalizer.normalize(lastName) + "\n" + householdNormalizer.normalize(address);
54	        try {
55	            byte[] digest = MessageDigest.getInstance("SHA-256")
56	                .digest(key.getBytes(StandardCharsets.UTF_8));
57	            StringBuilder hex = new StringBuilder(digest.length * 2);
58	            for (byte b : digest) {
59	                hex.append(String.format("%02x", b));
60	            }
61	            return hex.substring(0, ID_LENGTH).toUpperCase(Locale.ROOT);
62	        }
63	        catch (NoSuchAlgorithmException e) {
64	            throw new IllegalStateException("SHA-256 is required for household identifiers", e);
65	        }
66	    }
67	}
