58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final OwnerFieldsValidator ownerFieldsValidator;
76	
77	    private final PostcodeValidator postcodeValidator;
78	
79	    private final TelephoneNormalizer telephoneNormalizer;
80	
81	    private final EmailNormalizer emailNormalizer;
82	
83	    private final AddressNormalizer addressNormalizer;
84	
85	    private final BusinessDayResolver businessDayResolver;
86	
87	    private final OwnerAuditLogger ownerAuditLogger;
88	
89	    /** Maximum number of owners a single city may hold before further creations are rejected. */
90	    static final long MAX_OWNERS_PER_CITY = 50;
91	
92	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
93	    static final long MAX_OWNERS_PER_DAY = 100;
94	
95	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
96	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 OwnerFieldsValidator ownerFieldsValidator,
103	                                 PostcodeValidator postcodeValidator,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 EmailNormalizer emailNormalizer,
106	                                 AddressNormalizer addressNormalizer,
107	                                 BusinessDayResolver businessDayResolver,
108	                                 OwnerAuditLogger ownerAuditLogger) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.ownerFieldsValidator = ownerFieldsValidator;
114	        this.postcodeValidator = postcodeValidator;
115	        this.telephoneNormalizer = telephoneNormalizer;
116	        this.emailNormalizer = emailNormalizer;
117	        this.addressNormalizer = addressNormalizer;
118	        this.businessDayResolver = businessDayResolver;
119	        this.ownerAuditLogger = ownerAuditLogger;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
151	        this.ownerFieldsValidator.validate(ownerFieldsDto);
152	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
156	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
157	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
158	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
159	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
160	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
