137	    public Integer getNamesakeCount() {
138	        return this.namesakeCount;
139	    }
140	
141	    public void setNamesakeCount(Integer namesakeCount) {
142	        this.namesakeCount = namesakeCount;
143	    }
144	
145	    public String getMembershipNumber() {
146	        return this.membershipNumber;
147	    }
148	
149	    public void setMembershipNumber(String membershipNumber) {
150	        this.membershipNumber = membershipNumber;
151	    }
152	
153	    /**
154	     * Whether this owner was created after more than 80 owners had already been registered on the
155	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
156	     */
157	    public Boolean getBulkSignupWarning() {
158	        return this.bulkSignupWarning;
159	    }
160	
161	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
162	        this.bulkSignupWarning = bulkSignupWarning;
163	    }
164	
165	    /**
166	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
167	     * counting this owner) captured once at creation.
168	     */
169	    public Integer getHouseholdSize() {
170	        return this.householdSize;
171	    }
172	
173	    public void setHouseholdSize(Integer householdSize) {
174	        this.householdSize = householdSize;
175	    }
176	
177	    /**
178	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
179	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
180	     */
181	    public String getPostcode() {
182	        return this.postcode;
183	    }
184	
185	    public void setPostcode(String postcode) {
186	        this.postcode = postcode;
187	    }
188	
189	    /**
190	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
191	     */
192	    @Transient
193	    public String getDisplayName() {
194	        return this.getLastName() + ", " + this.getFirstName();
195	    }
196	
197	    /**
198	     * Return this owner's initials as the upper-cased first letters of the first and last
199	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
200	     */
201	    @Transient
202	    public String getInitials() {
203	        return initial(this.getFirstName()) + initial(this.getLastName());
204	    }
205	
206	    private static String initial(String name) {
207	        return Character.toUpperCase(name.charAt(0)) + ".";
208	    }
209	
210	    /** The membership level every owner starts at on creation. */
211	    private static final int BASE_MEMBERSHIP_LEVEL = 1;
212	
213	    /** The highest membership level derivable at creation; level 4 is reserved for tenure. */
214	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
215	
216	    /**
217	     * Return this owner's membership level, a number from 1 to 3 derived at creation: every owner
218	     * starts at {@value #BASE_MEMBERSHIP_LEVEL}; add 1 when an email address is present; add 1 when
219	     * the owner has no namesakes ({@code namesakeCount} is 0); capped at
220	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
221	     */
222	    @Transient
223	    public Integer getMembershipLevel() {
224	        int level = BASE_MEMBERSHIP_LEVEL;
225	        if (hasEmail()) {
226	            level++;
227	        }
228	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
229	            level++;
230	        }
231	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
232	    }
