56	    public ClinicServiceImpl(
57	        PetRepository petRepository,
58	        VetRepository vetRepository,
59	        OwnerRepository ownerRepository,
60	        VisitRepository visitRepository,
61	        SpecialtyRepository specialtyRepository,
62	        PetTypeRepository petTypeRepository,
63	        CustomerCodeGenerator customerCodeGenerator,
64	        HouseholdNormalizer householdNormalizer,
65	        HouseholdIdGenerator householdIdGenerator,
66	        MembershipNumberGenerator membershipNumberGenerator) {
67	        this.petRepository = petRepository;
68	        this.vetRepository = vetRepository;
